import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  texture,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'features-card-1-label';

  // ---- design tokens from spec ----
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = vec3(0.086, 0.086, 0.114); // #16161d
  const surfaceColor = vec3(0.043, 0.043, 0.063); // #0b0b10
  const accentColor = vec3(1.0, 0.165, 0.22); // #ff2a38

  // ---- placeholder texture, swapped in async (sync-safe) ----
  const placeholderTex = new THREE.Texture();
  const texNode = texture(placeholderTex);

  // ---- procedural TSL material: engineered gradient + subtle grain + accent underline ----
  const uvNode = uv();

  const gradient = mix(surfaceColor, inkColor, uvNode.y);

  // subtle static grain (hash-based, no time dependency -> static composition)
  const grainSeed = fract(
    sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grain = grainSeed.sub(0.5).mul(0.045);
  const withGrain = gradient.add(grain);

  // thin accent underline strip near bottom edge (<=10% of card area)
  const bandLow = smoothstep(0.0, 0.01, uvNode.y);
  const bandHigh = smoothstep(0.06, 0.05, uvNode.y);
  const band = bandLow.mul(bandHigh);
  const withAccent = mix(withGrain, accentColor, band.mul(0.85));

  // faint asset-informed overlay (kept subtle to preserve engineered-gradient read)
  const finalColor = mix(withAccent, texNode.rgb, float(0.08));

  const material = new MeshBasicNodeMaterial({ transparent: false });
  material.colorNode = finalColor;

  // card label plane dims match atlas rect aspect (512x320 -> 1.6:1)
  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);
  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // async texture load — cached loader, sync-safe swap-in
  let disposed = false;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTex) => {
      if (disposed) return;
      placeholderTex.image = loadedTex.image;
      placeholderTex.needsUpdate = true;
      material.needsUpdate = true;
    });
  }

  // ---- headline text: "Features 1" ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = headlineItem?.text ?? 'Features 1';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textMesh = ctx.fontAtlas.createText(headlineText, {
    fontSize,
    color: colors.paper ?? '#e8ecf2',
    align: 'left',
  });
  textMesh.position.set(-width / 2 + 0.15, 0, 0.03);
  group.add(textMesh);

  // ---- entrance: weighted-settle-style fade/rise, no idle motion (static composition) ----
  group.position.y += 0.15;
  const materials = [material];
  const opacityUniformTargets = [plane, textMesh];
  opacityUniformTargets.forEach((obj) => {
    obj.traverse?.((child) => {
      if (child.material) {
        child.material.transparent = true;
      }
    });
  });

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: group.position.y - 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    group.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );
  group.scale.set(0.98, 0.98, 0.98);

  // ---- handlers (static/non-interactive per spec) ----
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    geometry.dispose();
    material.dispose();
    placeholderTex.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
    group.remove(plane);
    group.remove(textMesh);
  };

  return group;
}
